import os
import shutil
import socket
import subprocess
import tempfile

from abc import ABCMeta, abstractmethod
from random import randint
from time import time, sleep, strftime
from importlib.resources import files
from taf.transport.ssh import connect as ssh_connect

from .exception import AdminApiException, AdminApiTerminatedException, AdminApiVersionMismatchException
from .util import (get_node_path, check_ip_address_format, create_empty_text_files, node_version_is_ok,
                   ensure_parent_dir_exists, get_node_version)


class AdminApiProcessControllerBase(metaclass=ABCMeta):

    PORT_RANGE = (49200, 64000)
    PORT_CHECK_MAX_RETRY = 20
    VERSION_MISMATCH_CODE = 21
    FORWARDER_MAX_RETRY = 2

    def __init__(self, bts_host, bts_port, username, password, use_ssl, update_interval, debug_log, bundle_path,
                 remote_host, remote_host_username, remote_host_password, logger, user_node_path):
        self.bts_host = bts_host
        self.bts_port = bts_port
        self.username = username
        self.password = password
        self.use_ssl = use_ssl
        self.update_interval = update_interval
        self.debug_log = debug_log
        self.bundle_path = bundle_path

        self.remote_host = remote_host
        self.ssh_username = remote_host_username
        self.ssh_password = remote_host_password
        self.forwarder = None
        self.bind_port = None

        self.process = None
        self.bundles_dir = None
        self.api_port = None
        self.stdout = None
        self.stderr = None
        self.stdout_file_path = None
        self.stderr_file_path = None

        self.logger = logger
        self.logger.debug("Looking for node.js")
        self.nodejs_bin = get_node_path(user_node_path)
        self.logger.debug("Node.js found in {}".format(self.nodejs_bin))
        self.logger.info("Node.js version: {}".format(get_node_version(self.nodejs_bin)))
        self.resource_dir = str(files("taf.internal.sbts.admin.cli").joinpath("resource"))
        self.ssh_remote_connection = None
        self.remote_temp_dir = None
        self.remote_api_process = None
        self.remote_process_pid = None

    def __setitem__(self, k, v):
        super().__setattr__(k, v)

    def start(self):
        """Start Admin API."""
        self._find_available_port()
        self._create_bundles_dir()
        self._prepare_remote_host_dir()
        self._start_api_process()
        self._start_api_process_remote()

    def stop(self):
        """Stop Admin API."""
        try:
            self._stop_api_process()
            self._log_proces_output()
            self._remove_bundles_dir()
            self._stop_api_process_remote()
            self._log_proces_output_remote()
            self._move_log_files_from_remote()
            self._clear_remote_directory()
            self._disconnect_from_remote()

        finally:
            self._close_stdout_files()

    def restart(self, log_output=True, setup_forwarder_timeout=10):
        """Restart Admin API process."""
        self.logger.info("Restart Admin API process")
        self._stop_api_process()
        self.logger.debug("API process stopped")
        if log_output:
            self._log_proces_output()
        if self.remote_host:
            self._stop_api_process_remote()
            self.logger.info("Remote API process stopped")
            self._start_api_process_remote(timeout=setup_forwarder_timeout)
            self.logger.info("Remote API process started succesfully")

        self._start_api_process()
        self.logger.debug("API process started succesfully")

    def change_proc_attributes(self, **kwargs):
        """change for kwargs attributes in a process controller instance"""
        for k, v in kwargs.items():
            if k in self.__dict__:
                self[k] = v

    def get_url(self):
        """Get Admin API server url."""
        if self.remote_host:
            return "ws://{}:{}".format(self.remote_host, self.api_port)
        return "ws://localhost:{}".format(self.api_port)

    def is_running(self):
        """Check if process is running."""
        if self.remote_host:
            return self.remote_api_process.is_alive()
        return self.process and not self._is_process_terminated()

    def assert_running(self):
        """Assert Admin API process is running."""
        if self.is_running():
            return
        exit, out, err = self._get_process_output()
        if exit == self.VERSION_MISMATCH_CODE:
            raise AdminApiVersionMismatchException(
                "EXIT CODE: {}\nSTDOUT:\n{}\nSTDERR:\n{}".format(exit, out, err))
        raise AdminApiTerminatedException(
            "ADMIN CLI TERMINATED\nEXIT CODE: {}\nSTDOUT:\n{}\nSTDERR:\n{}".format(exit, out, err))

    def _create_bundles_dir(self):
        if not self.remote_host:
            self.bundles_dir = tempfile.mkdtemp()
            self.logger.debug("Bundles directory {} created".format(self.bundles_dir))

    def _remove_bundles_dir(self):
        if self.bundles_dir and os.path.exists(self.bundles_dir):
            try:
                self.logger.info("Bundles directory exist: {}\n".format(self.bundles_dir))
                self._log_bundle_details()
            except Exception:
                self.logger.info("bundle file not found\n")
                pass
            shutil.rmtree(self.bundles_dir)
        else:
            self.logger.info("Bundles directory on local host not exist!\n")

    def _log_bundle_details(self):
        for filename in os.listdir(self.bundles_dir):
            statinfo = os.stat(os.path.join(self.bundles_dir, filename))
            self.logger.info("Admin bundle: {} ({} bytes)".format(
                filename, statinfo.st_size))

    def _prepare_remote_host_dir(self, timeout=10):
        if self.remote_host is None:
            return
        self.ssh_remote_connection = ssh_connect(hostname=self.remote_host,
                                                 username=self.ssh_username,
                                                 password=self.ssh_password,
                                                 port=22,
                                                 timeout=timeout)
        mktemp_proc = self.ssh_remote_connection.send_command("mktemp -d", timeout=timeout)
        temp_dir = mktemp_proc.read_output()
        self.logger.debug("Remote temp dir: {} created".format(temp_dir))
        self.remote_temp_dir = temp_dir.strip()
        self.ssh_remote_connection.execute("mkdir -p {}/resource/bin".format(self.remote_temp_dir), timeout=timeout)
        self.ssh_remote_connection.files.put(os.path.join(self.resource_dir, "bin", "main.bundle.js"),
                                             os.path.join(self.remote_temp_dir, "resource", "bin", "main.bundle.js"), 300)
        self.logger.debug("main.bundle.js transferred to: {}@{}:{} ".format(self.ssh_username, self.remote_host,
                                                                            os.path.join(self.remote_temp_dir, "resource", "bin", "main.bundle.js")))
        self.ssh_remote_connection.execute("mkdir -p {}/bundles".format(self.remote_temp_dir), timeout=timeout)
        if self.bundle_path:
            self.ssh_remote_connection.files.put(self.bundle_path,
                                                 os.path.join(self.remote_temp_dir, "bundles",
                                                              os.path.splitext(self.bundle_path)[0]), 300)

    def _start_api_process(self):
        if self.remote_host:
            return
        self.logger.debug("env variable PATH={}\n".format(os.environ.get("PATH")))
        self.logger.debug("env variable PYTHONPATH={}\n".format(os.environ.get("PYTHONPATH")))
        try:
            self.logger.debug("/opt/ute/node/:{}\n".format(os.listdir("/opt/ute/node/")))
        except Exception as e:
            self.logger.debug("/opt/ute/node/ not found: {} {}".format(type(e), e))
        cmd = self._get_cmd()
        self.logger.info(" ".join(cmd))
        if self.debug_log:
            self.stdout_file_path = "{}_stdout.txt".format(os.path.splitext(self.debug_log)[0])
            self.logger.debug("stdout.txt: {}".format(self.stdout_file_path))
            self.stderr_file_path = "{}_stderr.txt".format(os.path.splitext(self.debug_log)[0])
        else:
            self.stdout_file_path = "CLI_controller_stdout.txt"
            self.stderr_file_path = "CLI_controller_stderr.txt"
        try:
            create_empty_text_files([self.stdout_file_path, self.stderr_file_path])
            self.stdout = open(self.stdout_file_path, "r+")
            self.stderr = open(self.stderr_file_path, "r+")
        except Exception as e:
            self.stdout = None
            self.stderr = None
            self.logger.warning("Cannot create stdout and stderr files")
            self.logger.debug("AdminApiProcessControllerBase._start_api_process(): {} {}".format(type(e), e))
        self.process = subprocess.Popen(
            cmd, stdout=self.stdout, stderr=self.stderr)

    def _start_api_process_remote(self, timeout=20):
        if not self.remote_host:
            return
        no_proxy = os.environ.get("no_proxy")
        if no_proxy:
            no_proxy += ",{}".format(self.remote_host)
            os.environ["no_proxy"] = no_proxy
        else:
            os.environ["no_proxy"] = self.remote_host
        start_time = time()
        node_proc = self.ssh_remote_connection.send_command("node --version", timeout=timeout)
        node_ver = node_proc.read_output()
        if not node_version_is_ok(node_ver.encode('utf-8')):
            raise AdminApiException("node.js wrong version {}".format(node_ver))
        command = self._get_cmd_remote()
        while time() - start_time <= timeout:
            self.remote_api_process = self.ssh_remote_connection.send_command(command, timeout=180)
            self._get_remote_pid(command)
            self.logger.debug("remote Admin API PID: {}".format(self.remote_process_pid))
            sleep(2)
            if self.remote_api_process.is_alive():
                self._open_firewall()
                break

    def _open_firewall(self):
        try:
            self.ssh_remote_connection.execute("sudo iptables -I INPUT 1 -p tcp --dport {} -j ACCEPT".format(self.api_port),
                                               timeout=20)
        except Exception as e:
            self.logger.info("Firewall not oppened: {} {}".format(type(e), e))

    def _close_firewall(self):
        try:
            self.ssh_remote_connection.execute("sudo iptables -D INPUT -p tcp --dport {} -j ACCEPT".format(self.api_port),
                                               timeout=20)
        except Exception as e:
            self.logger.info("Firewall not closed: {} {}".format(type(e), e))

    def _get_remote_pid(self, command):
        ps_proc = self.ssh_remote_connection.send_command('ps -ax | grep "{}"'.format(command), timeout=20)
        output = ps_proc.read_output()
        self.remote_process_pid = output.split()[0]

    def _close_stdout_files(self):
        if self.remote_host:
            return
        try:
            self.stdout.close()
            self.stderr.close()
        except Exception as e:
            self.logger.warning("Cannot close stdout or stderr files")
            self.logger.debug("AdminApiProcessControllerBase._close_stdout_files(): {} {}".format(type(e), e))

    @abstractmethod
    def _get_cmd(self):
        """Get Admin CLI command."""

    @abstractmethod
    def _get_cmd_remote(self):
        """Get Admin CLI command for remote host."""

    def _stop_api_process(self):
        if self.remote_host:
            return
        if self.process and not self._is_process_terminated():
            self.process.terminate()
            if not self._process_terminates_within(2):
                self.process.kill()

        if self.is_running():
            self.logger.warning("Process is still running!")
            return

    def _stop_api_process_remote(self):
        if not self.remote_api_process:
            return
        self.ssh_remote_connection.execute("kill {}".format(self.remote_process_pid), timeout=20)
        sleep(5)
        self.ssh_remote_connection.execute("kill -SIGKILL {}".format(self.remote_process_pid), timeout=20)
        ps_proc = self.ssh_remote_connection.send_command("ps -{}".format(self.remote_process_pid))
        output = ps_proc.read_output()
        self.logger.debug("remote Admin API PID: {}".format(self.remote_process_pid))
        if not self.remote_process_pid:
            self.logger.warning("Remote Admin API process PID not found during teardown!")

        if self.remote_process_pid and self.remote_process_pid in output:
            self.logger.warning("Remote Admin API process NOT terminated!")
        else:
            self.logger.debug("Remote Admin API process terminated")
        self.remote_process_pid = None
        self._close_firewall()

    def _process_terminates_within(self, timeout):
        start = time()
        while not self._is_process_terminated():
            if time() - start >= timeout:
                return False
            else:
                sleep(0.25)
        return True

    def _is_process_terminated(self):
        return self.process.poll() is not None

    def _log_proces_output(self):
        if not self.process:
            return
        exit_code, out, err = self._get_process_output()
        self.logger.info("Exit code: {}".format(exit_code))
        self.logger.debug("STDOUT\n{}".format(out))
        self.logger.debug("STDERR\n{}".format(err))

    def _log_proces_output_remote(self):
        if not self.remote_api_process:
            self.logger.debug("self.remote_api_process is None. Skipping _log_proces_output_remote")
            return
        try:
            if not self.remote_api_process.is_alive():
                exit_code = self.remote_api_process.get_exit_code()
                self.logger.info("Exit code: {}".format(exit_code))
            out = self.remote_api_process.read_output()
            self.logger.info("STDOUT\n{}".format(out))
            err = self.remote_api_process.read_error()
            self.logger.info("STDERR\n{}".format(err))
        except Exception as e:
            self.logger.debug("Some problems occured during _log_proces_output_remote: {} {}".format(type(e), e))

    # flake8: noqa: C901
    def _get_process_output(self):
        try:
            exit_code = self.process.poll()
        except Exception as e:
            self.logger.debug("Process not found: {} {}".format(type(e), e))
            exit_code = None
        try:
            with open(self.stdout_file_path) as stdout_file:
                out = stdout_file.read()
        except Exception as e:
            self.logger.debug("Stdout file: {} not found.\nInitial error: {} {}".format(self.stdout_file_path, type(e), e))
            out = None
        try:
            with open(self.stderr_file_path) as stderr_file:
                err = stderr_file.read()
        except Exception as e:
            self.logger.debug("Error file: {} not found.\nInitial error: {} {}".format(self.stderr_file_path, type(e), e))
            err = None
        return exit_code, out, err

    def _find_available_port(self):
        for i in range(self.PORT_CHECK_MAX_RETRY):
            port = randint(*self.PORT_RANGE)
            if self._test_port(port):
                self.api_port = port
                return
        raise AdminApiException(
            "Can't find available port for Admin API server.")

    def _test_port(self, port):
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            s.bind(("localhost", int(port)))
        except OSError:
            return False
        else:
            s.close()
            return True

    def _move_log_files_from_remote(self):
        if not self.remote_api_process:
            return
        self.logger.debug("self.debug_log: {}".format(self.debug_log))
        if os.path.isfile(self.debug_log):
            current_time = strftime("_%Y-%m-%d_%H-%M-%S")
            renamed_log = "".join([os.path.splitext(self.debug_log)[0], current_time, ".log"])
            try:
                os.rename(self.debug_log, renamed_log)
                self.logger.info("{} exist. Renamed to {}".format(self.debug_log, renamed_log))
            except Exception as e:
                self.logger.info("Cannot renamed {} to {}".format(self.debug_log, renamed_log))
                self.logger.info("{} {}".format(type(e), e))

        local_api_log_dirname = os.path.dirname(self.debug_log)
        files_list = self._get_admin_log_files_list()
        self.logger.debug("files_list: {}".format(files_list))
        if local_api_log_dirname and local_api_log_dirname.startswith("/"):

            self._download_files(files_list, os.path.dirname(self.debug_log))
            self.logger.debug("admin_api.log downloaded to {}".format(self.debug_log))
        else:
            local_api_log_path = os.path.abspath(os.path.dirname(self.debug_log))
            self.logger.debug("remote_api_log: {}".format(local_api_log_path))

            self._download_files(files_list, local_api_log_path)
            self.logger.debug("admin_api.log downloaded to {}".format(local_api_log_path))

    def _get_admin_log_files_list(self):
        files_list = self.ssh_remote_connection.files.listdir(self.remote_temp_dir)
        pattern = os.path.splitext(self.debug_log.split('/')[-1])[0]
        return [f for f in files_list if f.startswith(pattern)]

    def _download_files(self, files_list, target_directory):
        ensure_parent_dir_exists(os.path.join(target_directory, "a"))
        for f in files_list:
            filename = f.split('/')[-1]
            self.ssh_remote_connection.files.get(os.path.join(self.remote_temp_dir, f),
                                                 os.path.join(target_directory, filename), 600)

    def _clear_remote_directory(self):
        if not self.remote_api_process:
            return
        self.ssh_remote_connection.execute("rm -rf {}".format(self.remote_temp_dir), 600)

    def _disconnect_from_remote(self):
        if not self.remote_api_process:
            return
        self.ssh_remote_connection.disconnect()
        self.remote_api_process = None


class AdminApiProcessController_v2(AdminApiProcessControllerBase):

    def _get_cmd(self):
        api_script = os.path.join(self.resource_dir, "bin", "main.bundle.js")

        if self.bts_host != "localhost":
            self.bts_host = check_ip_address_format(self.bts_host)
        if not self.nodejs_bin:
            raise AdminApiException(
                "NodeJS not installed or wrong version.\n"
                "Please install taf.internal.node library or add NodeJS (`node`) "
                "to PATH environment variable")
        cmd = [
            self.nodejs_bin, "--expose-gc", api_script,
            "--bts-host={}".format(
                self.bts_host if not self.remote_host else "localhost"),
            "--bts-port={}".format(
                self.bts_port if not self.remote_host else self.bind_port),
            "--bts-username={}".format(self.username),
            "--bts-password={}".format(self.password),
            "--debug={}".format(self.debug_log),
            "--interval={}".format(self.update_interval),
            "--cli-port={}".format(self.api_port),
            "--bundles-dir={}".format(self.bundles_dir),
            "--output-file={}_disconnect_at_.ims2".format(os.path.splitext(self.debug_log)[0])
        ]

        if self.bundle_path:
            cmd.append("--bundle-path={}".format(self.bundle_path))

        if not self.use_ssl:
            cmd.append("--insecure")
        return cmd

    def _get_cmd_remote(self):

        api_script = os.path.join(self.remote_temp_dir, "resource", "bin", "main.bundle.js")
        self.api_port = randint(*self.PORT_RANGE)
        if self.bts_host != "localhost":
            self.bts_host = check_ip_address_format(self.bts_host)
        admin_api_log_name = self.debug_log.split('/')[-1]
        admin_api_log_path = os.path.join(self.remote_temp_dir, self.debug_log.split('/')[-1])
        disconnect_logs_path = os.path.join(self.remote_temp_dir, os.path.splitext(admin_api_log_name)[0])
        cmd = [
            "node", "--expose-gc", api_script,
            "--bts-host={}".format(self.bts_host),
            "--bts-port={}".format(self.bts_port),
            "--bts-username={}".format(self.username),
            "--bts-password={}".format(self.password),
            "--debug={}".format(admin_api_log_path),
            "--interval={}".format(self.update_interval),
            "--cli-port={}".format(self.api_port),
            "--cli-host=0.0.0.0",
            "--bundles-dir={}".format(os.path.join(self.remote_temp_dir, "bundles")),
            "--output-file={}_disconnect_at_.ims2".format(disconnect_logs_path)
        ]

        if self.bundle_path:
            cmd.append("--bundle-path={}".format(os.path.join(self.remote_temp_dir, "bundles",
                                                              os.path.splitext(self.bundle_path)[0])))

        if not self.use_ssl:
            cmd.append("--insecure")
        cmd = " ".join(cmd)
        self.logger.debug("remote Admin API command: {}".format(cmd))
        return cmd
